-------------------------------------------------------------------------------
-- clkdiv4: bus clock = memory clock / 4, 50 % duty, with the phase
-------------------------------------------------------------------------------
-- The bus clock is derived from the memory clock here, not generated by its own
-- PLL output, for two reasons (Stage 2):
--
--   * the SDRAM controller (Task 3) schedules its bursts against the bus clock
--     and needs a fixed phase between the two - two free-running PLL outputs of
--     4:1 ratio have an undefined relative phase, a divider has one by
--     construction (BUS_PHASE says exactly where in the memory-clock group of
--     four the bus edge is);
--   * one clkmux2 then switches bus and memory clock together on DS80, so the
--     phase can never change across a switch (a second mux for a second bus
--     PLL output could select them out of step).
--
-- A 2-bit counter on the rising edge of clk_in; clk_out is registered with bit
-- 1 of that counter inverted, so it rises on the clk_in edge where the counter
-- becomes "00" and stays high for the phases 00 and 01: clk_out is a 50 % duty
-- clock of exactly 2 x clk_in periods high and 2 low, its rising edge
-- coinciding with the clk_in rising edge of phase "00". `phase` is the counter
-- value (same clock domain as clk_in): the clock.vhd note there says why the 50
-- % duty matters (the falling-edge ena_cnt).
--
-- clk_out is a fabric register driving clock loads, like the clkmux2 output it
-- is plain logic that Quartus binds onto the clock network (fitter: global
-- clock with a register source, clkdiv4|q); no vendor cell is instantiated, so
-- GHDL analyses this file as it is.
--
-- rst is synchronous to clk_in: while asserted the counter holds "11" and
-- clk_out '0' - the bus clock is held LOW in reset. The memory controller's
-- cpu_sample is a clk_out rising edge: held high instead, it waited up to 3
-- extra bus periods for its first sample after release while T80s was
-- already running. The first clk_in edge after release takes cnt "11" ->
-- "00" and raises clk_out at BUS_PHASE "00"; q only changes on clk_in
-- edges, so no runt pulses.
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.numeric_std.all;

entity clkdiv4 is
port (
	clk_in  : in  std_logic;
	rst     : in  std_logic;
	clk_out : out std_logic;
	phase   : out std_logic_vector(1 downto 0)
);
end clkdiv4;

architecture rtl of clkdiv4 is

signal cnt : unsigned(1 downto 0) := "11";
signal q   : std_logic := '0';

begin

div: process (clk_in)
	variable nxt : unsigned(1 downto 0);
begin
	if rising_edge(clk_in) then
		if rst = '1' then
			cnt <= "11";
			q   <= '0';
		else
			nxt := cnt + 1;
			cnt <= nxt;
			q   <= not nxt(1);
		end if;
	end if;
end process;

clk_out <= q;
phase   <= std_logic_vector(cnt);

end rtl;
